import { imageAssets } from '@/content/image-assets.generated'

export type FigureImage = {
  src: string
  srcSet: string
  width: number
  height: number
}

export type LogoImage = {
  src: string
  width: number
  height: number
}

// Resolves Dashboard image filenames to WebP generated by scripts/build-images.mjs
// from assets/sources/. A filename without an uploaded source resolves to null.
export function figureImage(
  family: 'projects' | 'publication-highlights',
  slug: string,
  filename: string | null | undefined
): FigureImage | null {
  const name = filename?.trim()
  if (!name) return null

  return imageAssets.figures[`${family}/${slug}/${name}`] ?? null
}

export function logoImage(
  filename: string | null | undefined
): LogoImage | null {
  const name = filename?.trim()
  if (!name) return null

  return imageAssets.logos[name] ?? null
}
